void sum(int a, int b)                       // method signature
{
    System.out.println(a + b);               // method implementation (body)
}

abstract class Payment {
    abstract void pay(int amount)       // no semicolon
}

class Payment {
    abstract void pay(int amount);
}

abstract class Payment {
    abstract void pay(int amount);
}

abstract class Payment {
    abstract void pay(int amount);
}
class UPI extends Payment {
    void pay(int amount) {
        System.out.println("Paid " + amount + " using UPI");
    }
}
class Card extends Payment {
    void pay(int amount) {
        System.out.println("Paid " + amount + " using Card");
    }
}
class Wallet extends Payment {
    void pay(int amount) {
        System.out.println("Paid " + amount + " using Wallet");
    }
}
public class Main {
    public static void main(String[] args) {
        Payment p1 = new UPI();
        Payment p2 = new Card();
        Payment p3 = new Wallet();
        p1.pay(500);
        p2.pay(1000);
        p3.pay(1500);
    }
}

abstract class Payment {
    abstract void pay(int amount);
}

public class Main {
    public static void main(String[] args) {
        Payment p = new Payment();   // compilation error
    }
}

abstract class Bird {
    abstract void fly();
}
class Ostrich extends Bird {
    void fly() {
        System.out.println("Ostrich cannot fly");
    }
}
class Eagle extends Bird {
    void fly() {
        System.out.println("Eagle flies high");
    }
}
public class Main {
    public static void main(String[] args) {
        Bird b1 = new Ostrich();
        Bird b2 = new Eagle();
        b1.fly();
        b2.fly();
    }
}

abstract class Bird {
    abstract void fly();
}
class Eagle extends Bird {      // fly() body is missing
}

abstract class Demo1 { }
class Demo2 extends Demo1 { }              // normal extends abstract
class Demo3 { }
abstract class Demo4 extends Demo3 { }     // abstract extends normal
abstract class Demo5 extends Demo1 { }     // abstract extends abstract

